/**
 * Helper to retrieve canonical verses for any key registered full chapter
 */
export function getRegisteredFullChapter(bookName: string, chapter: number): BibleVerse[] | null {
  const normalizedBook = bookName.trim().replace(/\s+/g, "-").toLowerCase();
  const key = `${normalizedBook}-${chapter}`;
  if (FULL_CHAPTERS_REGISTRY[key]) {
    return FULL_CHAPTERS_REGISTRY[key];
  }
  // Alternate key check for "psalm" vs "psalms"
  if (normalizedBook === "psalm" && FULL_CHAPTERS_REGISTRY[`psalms-${chapter}`]) {
    return FULL_CHAPTERS_REGISTRY[`psalms-${chapter}`];
  }
  if (normalizedBook === "psalms" && FULL_CHAPTERS_REGISTRY[`psalm-${chapter}`]) {
    return FULL_CHAPTERS_REGISTRY[`psalm-${chapter}`];
  }
  return null;
}
